1	package main
2	
3	import (
4		"bytes"
5		"encoding/binary"
6		"math"
7		mrand "math/rand"
8		"time"
9	
10		"github.com/hajimehoshi/ebiten/v2/audio"
11	)
12	
13	const sampleRate = 44100
14	
15	type SoundManager struct {
16		ctx *audio.Context
17	
18		fire      []byte
19		thrust    []byte
20		beat1     []byte
21		beat2     []byte
22		bangSmall []byte
23		bangMed   []byte
24		bangLarge []byte
25		ufoBig    []byte
26		ufoSmall  []byte
27		ufoFire   []byte
28		shipBoom  []byte
29	
30		thrustPlayer *audio.Player
31		ufoPlayer    *audio.Player
32		oneShots     []*audio.Player
33		ufoLoopSize  int
34		nextBeat     time.Time
35		quietUntil   time.Time
36		beatFlip     bool
37	}
38	
39	func NewSoundManager() *SoundManager {
40		ctx := audio.CurrentContext()
41		if ctx == nil {
42			ctx = audio.NewContext(sampleRate)
43		}
44	
45		sm := &SoundManager{
46			ctx:         ctx,
47			ufoLoopSize: -1,
48		}
49	
50		sm.fire = generateSweep(1250, 620, 0.09, 0.28, waveSquare, 18.0)
51		sm.thrust = generateThrust()
52		sm.beat1 = generateTone(110, 0.09, 0.28, waveSquare, 0.03)
53		sm.beat2 = generateTone(82, 0.09, 0.30, waveSquare, 0.03)
54		sm.bangSmall = generateExplosion(0.14, 0.34, 190, 90)
55		sm.bangMed = generateExplosion(0.22, 0.42, 130, 55)
56		sm.bangLarge = generateExplosion(0.32, 0.48, 90, 32)
57		sm.ufoBig = generateSaucerLoop(150, 108, 0.86, 0.16)
58		sm.ufoSmall = generateSaucerLoop(315, 235, 0.66, 0.14)
59		sm.ufoFire = generateSweep(980, 420, 0.08, 0.24, waveSquare, 16.0)
60		sm.shipBoom = generateShipExplosion()
61		sm.nextBeat = time.Now().Add(700 * time.Millisecond)
62	
63		return sm
64	}
65	
66	func (sm *SoundManager) Update(g *Game) {
67		if sm == nil || g == nil {
68			return
69		}
70		sm.cleanupOneShots()
71	
72		now := time.Now()
73		if g.GameState != 0 {
74			sm.stopThrust()
75			sm.stopUFOLoop()
76			return
77		}
78	
79		if now.Before(sm.quietUntil) {
80			sm.stopThrust()
81			sm.stopUFOLoop()
82			return
83		}
84	
85		if g.Ship != nil && g.Ship.IsThrusting {
86			sm.startThrust()
87		} else {
88			sm.stopThrust()
89		}
90	
91		hasSmall := false
92		hasBig := false
93		for _, u := range g.UFOs {
94			if u.Size == 0 {
95				hasSmall = true
96			} else {
97				hasBig = true
98			}
99		}
100		if hasSmall {
101			sm.startUFOLoop(0)
102		} else if hasBig {
103			sm.startUFOLoop(1)
104		} else {
105			sm.stopUFOLoop()
106		}
107	
108		if !now.Before(sm.nextBeat) {
109			if sm.beatFlip {
110				sm.play(sm.beat2)
111			} else {
112				sm.play(sm.beat1)
113			}
114			sm.beatFlip = !sm.beatFlip
115	
116			remaining := len(g.Asteroids)
117			interval := 250 + remaining*70
118			if interval > 900 {
119				interval = 900
120			}
121			sm.nextBeat = now.Add(time.Duration(interval) * time.Millisecond)
122		}
123	}
124	
125	func (sm *SoundManager) PlayShipFire() {
126		sm.play(sm.fire)
127	}
128	
129	func (sm *SoundManager) PlayUFOFire() {
130		sm.play(sm.ufoFire)
131	}
132	
133	func (sm *SoundManager) PlayShipExplosion() {
134		sm.quietUntil = time.Now().Add(650 * time.Millisecond)
135		sm.stopThrust()
136		sm.stopUFOLoop()
137		sm.play(sm.shipBoom)
138	}
139	
140	func (sm *SoundManager) PlayAsteroidHit(size int) {
141		switch size {
142		case 1:
143			sm.play(sm.bangSmall)
144		case 2:
145			sm.play(sm.bangMed)
146		default:
147			sm.play(sm.bangLarge)
148		}
149	}
150	
151	func (sm *SoundManager) PlayUFOHit(size int) {
152		if size == 0 {
153			sm.play(sm.bangSmall)
154			return
155		}
156		sm.play(sm.bangMed)
157	}
158	
159	func (sm *SoundManager) startThrust() {
160		if sm.thrustPlayer != nil && sm.thrustPlayer.IsPlaying() {
161			return
162		}
163		if sm.thrustPlayer != nil {
164			_ = sm.thrustPlayer.Close()
165			sm.thrustPlayer = nil
166		}
167		player := sm.ctx.NewPlayerFromBytes(sm.thrust)
168		sm.thrustPlayer = player
169		player.Play()
170	}
171	
172	func (sm *SoundManager) stopThrust() {
173		if sm.thrustPlayer == nil {
174			return
175		}
176		sm.thrustPlayer.Pause()
177		_ = sm.thrustPlayer.Close()
178		sm.thrustPlayer = nil
179	}
180	
181	func (sm *SoundManager) startUFOLoop(size int) {
182		if sm.ufoPlayer != nil && sm.ufoPlayer.IsPlaying() && sm.ufoLoopSize == size {
183			return
184		}
185		sm.stopUFOLoop()
186	
187		var sound []byte
188		if size == 0 {
189			sound = sm.ufoSmall
190		} else {
191			sound = sm.ufoBig
192		}
193		player := sm.ctx.NewPlayerFromBytes(sound)
194		sm.ufoPlayer = player
195		sm.ufoLoopSize = size
196		player.Play()
197	}
198	
199	func (sm *SoundManager) stopUFOLoop() {
200		if sm.ufoPlayer == nil {
201			sm.ufoLoopSize = -1
202			return
203		}
204		sm.ufoPlayer.Pause()
205		_ = sm.ufoPlayer.Close()
206		sm.ufoPlayer = nil
207		sm.ufoLoopSize = -1
208	}
209	
210	func (sm *SoundManager) Close() {
211		if sm == nil {
212			return
213		}
214		sm.stopThrust()
215		sm.stopUFOLoop()
216		for _, p := range sm.oneShots {
217			p.Pause()
218			_ = p.Close()
219		}
220		sm.oneShots = nil
221	}
222	
223	func (sm *SoundManager) play(sound []byte) {
224		if sm == nil || len(sound) == 0 {
225			return
226		}
227		p := sm.ctx.NewPlayerFromBytes(sound)
228		sm.oneShots = append(sm.oneShots, p)
229		p.Play()
230	}
231	
232	func (sm *SoundManager) cleanupOneShots() {
233		active := sm.oneShots[:0]
234		for _, p := range sm.oneShots {
235			if p.IsPlaying() {
236				active = append(active, p)
237				continue
238			}
239			_ = p.Close()
240		}
241		sm.oneShots = active
242	}
243	
244	const (
245		waveSquare = iota
246		waveSaw
247	)
248	
249	func generateTone(freq float64, seconds float64, volume float64, wave int, decay float64) []byte {
250		count := int(float64(sampleRate) * seconds)
251		buf := bytes.NewBuffer(make([]byte, 0, count*2))
252	
253		for i := 0; i < count; i++ {
254			t := float64(i) / sampleRate
255			amp := 1.0
256			if decay > 0 {
257				amp = math.Exp(-decay * t)
258			}
259	
260			phase := 2 * math.Pi * freq * t
261			var v float64
262			switch wave {
263			case waveSaw:
264				saw := 2 * (t*freq - math.Floor(0.5+t*freq))
265				v = saw
266			default:
267				if math.Sin(phase) >= 0 {
268					v = 1
269				} else {
270					v = -1
271				}
272			}
273	
274			sample := int16(v * volume * amp * math.MaxInt16)
275			_ = binary.Write(buf, binary.LittleEndian, sample)
276		}
277	
278		return buf.Bytes()
279	}
280	
281	func generateSweep(startFreq float64, endFreq float64, seconds float64, volume float64, wave int, decay float64) []byte {
282		count := int(float64(sampleRate) * seconds)
283		buf := bytes.NewBuffer(make([]byte, 0, count*2))
284	
285		phase := 0.0
286		for i := 0; i < count; i++ {
287			progress := float64(i) / float64(count)
288			t := float64(i) / sampleRate
289			freq := startFreq + (endFreq-startFreq)*progress
290			phase += 2 * math.Pi * freq / sampleRate
291			amp := math.Exp(-decay * t)
292	
293			v := sampleWave(phase, wave)
294			writeSample(buf, v*volume*amp)
295		}
296	
297		return buf.Bytes()
298	}
299	
300	func generateThrust() []byte {
301		count := int(float64(sampleRate) * 0.18)
302		buf := bytes.NewBuffer(make([]byte, 0, count*2))
303	
304		phase := 0.0
305		for i := 0; i < count; i++ {
306			t := float64(i) / sampleRate
307			phase += 2 * math.Pi * 78 / sampleRate
308			flutter := 0.75 + 0.25*math.Sin(2*math.Pi*22*t)
309			noise := (mrand.Float64()*2 - 1) * 0.18
310			rumble := sampleWave(phase, waveSaw) * 0.30
311			writeSample(buf, (rumble+noise)*flutter)
312		}
313	
314		return buf.Bytes()
315	}
316	
317	func generateSaucerLoop(highFreq float64, lowFreq float64, seconds float64, volume float64) []byte {
318		count := int(float64(sampleRate) * seconds)
319		buf := bytes.NewBuffer(make([]byte, 0, count*2))
320	
321		phase := 0.0
322		for i := 0; i < count; i++ {
323			t := float64(i) / sampleRate
324			pulse := math.Mod(t, 0.18)
325			freq := lowFreq
326			if pulse < 0.09 {
327				freq = highFreq
328			}
329			phase += 2 * math.Pi * freq / sampleRate
330			gate := 0.35
331			if pulse < 0.12 {
332				gate = 1.0
333			}
334			writeSample(buf, sampleWave(phase, waveSquare)*volume*gate)
335		}
336	
337		return buf.Bytes()
338	}
339	
340	func generateExplosion(seconds float64, volume float64, startRumble float64, endRumble float64) []byte {
341		count := int(float64(sampleRate) * seconds)
342		buf := bytes.NewBuffer(make([]byte, 0, count*2))
343	
344		phase := 0.0
345		for i := 0; i < count; i++ {
346			progress := float64(i) / float64(count)
347			t := float64(i) / sampleRate
348			freq := startRumble + (endRumble-startRumble)*progress
349			phase += 2 * math.Pi * freq / sampleRate
350	
351			envelope := math.Exp(-5.4 * t / seconds)
352			crackle := (mrand.Float64()*2 - 1) * envelope
353			rumble := sampleWave(phase, waveSquare) * envelope * 0.42
354			writeSample(buf, (crackle+rumble)*volume)
355		}
356	
357		return buf.Bytes()
358	}
359	
360	func generateShipExplosion() []byte {
361		seconds := 0.62
362		count := int(float64(sampleRate) * seconds)
363		buf := bytes.NewBuffer(make([]byte, 0, count*2))
364	
365		rumblePhase := 0.0
366		whinePhase := 0.0
367		for i := 0; i < count; i++ {
368			progress := float64(i) / float64(count)
369			t := float64(i) / sampleRate
370	
