	sm.stopThrust()
	sm.stopUFOLoop()
	for _, p := range sm.oneShots {
		p.Pause()
		_ = p.Close()
	}
	sm.oneShots = nil
}

func (sm *SoundManager) play(sound []byte) {
	if sm == nil || len(sound) == 0 {
		return
	}
	p := sm.ctx.NewPlayerFromBytes(sound)
