func generateTone(freq float64, seconds float64, volume float64, wave int, decay float64) []byte {
	count := int(float64(sampleRate) * seconds)
	buf := bytes.NewBuffer(make([]byte, 0, count*2))

	for i := 0; i < count; i++ {
		t := float64(i) / sampleRate
		amp := 1.0
		if decay > 0 {
